/* The only script on this page, and deliberately the smallest thing that can work:
   one click handler, no timers, no dates, no state. Both "Back to the campaign"
   links are real <a href="/"> and behave normally with JS off, on a direct arrival
   from a shared link, or if anything below throws.

   The upgrade to a true Back only happens when the visitor demonstrably arrived
   from the campaign page, so history.back() can never walk someone off the site.
   A forward navigation to "/" always lands at scroll 0; history.back() restores
   the exact position they left, which is the whole point. */
(function(){
  try{
    var ref = document.referrer; if(!ref) return;
    var u = new URL(ref, location.href);
    if(u.origin !== location.origin) return;
    if(u.pathname !== '/' && u.pathname !== '/index.html') return;
    if(history.length < 2) return;
    [].forEach.call(document.querySelectorAll('a.back'), function(a){
      a.addEventListener('click', function(e){
        if(e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
        e.preventDefault(); history.back();
      });
    });
  }catch(e){}
})();

